// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address originalDao, address newDao, address caller) public {
        vm.assume(caller != originalDao);
        vm.assume(caller != address(0));
        vm.assume(originalDao != address(0));
        vm.assume(newDao != originalDao);

        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
        c.setDAO(originalDao);
        c.endConfiguration();

        bytes32 beforeHash = keccak256(abi.encodePacked(c.DAO()));
        vm.prank(caller);
        try c.setDAO(newDao) {} catch {}

        address afterDao = c.DAO();
        bytes32 afterHash = keccak256(abi.encodePacked(afterDao));
        assertEq(afterHash, beforeHash);
    }
}

